<script setup lang="ts">
import {ref,watch,onMounted,onUnmounted} from 'vue'
import {ArrowLeft,Plus,Check} from 'lucide-vue-next'
import {useLocal} from '../stores/local'
import type {Document} from '../domain/local-contract'
import {emptyMediaProvider,type MediaProtocol,type MediaProvider} from './contract'
import {mediaProviders,saveMediaProvider,selectMediaDefault,type MediaDefaults,type MediaPurpose} from './runtime'
const store=useLocal(),rows=ref<Document<MediaProvider>[]>([]),defaults=ref<Document<MediaDefaults>|null>(null),protocol=ref<MediaProtocol>('openai-images'),editing=ref<MediaProvider|null>(null),revision=ref(0),error=ref(''),busy=ref(false)
const names={'openai-images':'图像','openai-tts':'在线配音','openai-asr':'语音转录','openai-embeddings':'向量','runway-video':'视频'},purpose=(p:MediaProtocol):MediaPurpose=>p==='openai-images'?'image':p==='openai-tts'?'tts':p==='openai-asr'?'asr':p==='runway-video'?'video':'embedding';let disposed=false
watch(()=>editing.value?.protocol,p=>{if(p==='runway-video'&&editing.value&&!editing.value.videoCapabilities)editing.value.videoCapabilities=emptyMediaProvider(p).videoCapabilities})
watch(()=>editing.value?.modelId,(id,old)=>{if(old&&id!==old&&editing.value?.videoCapabilities)editing.value.videoCapabilities.creditsPerSecond=null})
async function load(){const vault=store.vault;if(!vault)return;const [profiles,settings]=await Promise.all([mediaProviders(vault),vault.read<MediaDefaults>('settings:media-defaults')]);if(disposed||store.vault!==vault||!vault.unlocked)return;rows.value=profiles;defaults.value=settings}
function create(){editing.value=emptyMediaProvider(protocol.value);revision.value=0;error.value=''}
function edit(row:Document<MediaProvider>){editing.value=structuredClone(row.value);revision.value=row.revision;error.value=''}
async function save(){const vault=store.vault,value=editing.value;if(!vault||!value||busy.value)return;busy.value=true;error.value='';try{await saveMediaProvider(vault,value.id,revision.value,{...value});if(disposed||store.vault!==vault)return;editing.value=null;await load()}catch(e){if(!disposed)error.value=(e as Error).message}finally{if(!disposed)busy.value=false}}
async function select(row:Document<MediaProvider>){const vault=store.vault;if(!vault||busy.value)return;busy.value=true;try{await selectMediaDefault(vault,row);await load()}catch(e){if(!disposed)error.value=(e as Error).message}finally{if(!disposed)busy.value=false}}
onMounted(()=>void load().catch(e=>error.value=(e as Error).message));onUnmounted(()=>{disposed=true;if(editing.value)editing.value.key='';editing.value=null;rows.value=[]})
</script>
<template><section><div class="final-page-heading"><div class="final-heading-copy"><RouterLink to="/local/settings/models" class="final-text-link"><ArrowLeft :size="17"/>模型</RouterLink><h1>媒体通道</h1><RouterLink to="/local/vectors" class="final-text-link">内容索引</RouterLink><RouterLink to="/local/video" class="final-text-link">视频创作</RouterLink></div><button v-if="editing" @click="editing=null">返回列表</button></div><p v-if="error" role="alert" class="final-error">{{error}}</p><form v-if="editing" class="final-card-form" @submit.prevent="save"><label>名称<input v-model="editing.name" maxlength="200" required></label><label>用途<select aria-label="用途" v-model="editing.protocol"><option v-for="(label,key) in names" :key="key" :value="key">{{label}}</option></select></label><label>API 地址<input v-model="editing.baseUrl" required autocomplete="off" spellcheck="false"></label><label>模型 ID<input v-model="editing.modelId" required maxlength="300" autocomplete="off" spellcheck="false"></label><label>API Key<input v-model="editing.key" type="password" autocomplete="new-password" maxlength="16000"></label><label v-if="editing.protocol==='openai-images'">图片返回格式<select v-model="editing.imageFormat"><option value="gpt-image">GPT Image · PNG</option><option value="compatible-b64">兼容协议 · base64</option></select></label><fieldset v-if="editing.protocol==='runway-video'&&editing.videoCapabilities" class="final-video-caps"><legend>已确认的模型能力</legend><label class="final-check"><input v-model="editing.videoCapabilities.text" type="checkbox">文字生成视频</label><label class="final-check"><input v-model="editing.videoCapabilities.image" type="checkbox">参考图生成视频</label><label>估价 · 积分 / 秒<input v-model.number="editing.videoCapabilities.creditsPerSecond" type="number" min="0" max="1000000" step="0.1"></label><a :href="editing.videoCapabilities.pricingSource" target="_blank" rel="noopener noreferrer" class="final-text-link">价格来源</a></fieldset><label v-if="editing.protocol==='openai-tts'">音色<input v-model="editing.voice" maxlength="200" required></label><details><summary>调用上限与超时</summary><label>设备每日调用上限<input v-model.number="editing.dailyCalls" type="number" min="1" max="10000" required></label><label>首包 · 毫秒<input v-model.number="editing.firstPacketMs" type="number" min="100" max="3600000"></label><label>空闲 · 毫秒<input v-model.number="editing.idleMs" type="number" min="100" max="3600000"></label><label>总等待 · 毫秒<input v-model.number="editing.totalMs" type="number" min="100" max="3600000"></label><label class="final-check"><input v-model="editing.enabled" type="checkbox">启用</label></details><button class="final-primary" :disabled="busy">保存通道</button></form><template v-else><div class="final-model-create"><label>用途<select aria-label="用途" v-model="protocol"><option v-for="(label,key) in names" :key="key" :value="key">{{label}}</option></select></label><button class="final-primary" @click="create"><Plus :size="18"/>添加通道</button></div><div class="final-settings"><article v-for="row in rows" :key="row.id" class="final-setting-card"><h2>{{row.value.name}}</h2><p class="final-subtle">{{row.value.modelId}} · {{names[row.value.protocol]}}</p><p v-if="defaults?.value.profiles[purpose(row.value.protocol)]===row.id" class="final-subtle"><Check :size="16"/>默认通道</p><div class="final-grid-actions"><button @click="edit(row)">编辑</button><button :disabled="busy||!row.value.enabled" @click="select(row)">设为默认</button></div></article></div><p v-if="!rows.length" class="final-subtle">为图像、配音与转录各选一个支持该用途的供应商。</p></template></section></template>
